const vars = $('Edit Fields - Variaveis').first().json;
return $input.all().map(item => ({
  json: {
    tableId: item.json.id,
    tableName: item.json.name,
    schemaTableName: 'data_table_user_' + item.json.id,
    username: vars.username,
    token: vars.token,
    repositorio: vars.repositorio,
    nome: vars.nome,
    email: vars.email
  }
}));

const tableId = $('Code - Mapear Variaveis').item.json.tableId;
const tableName = $('Code - Mapear Variaveis').item.json.tableName;
const repositorio = $('Code - Mapear Variaveis').item.json.repositorio;

// Pega todos os registros do Aggregate
const allItems = $input.all();
let rows = [];

// Se o Aggregate retornou um item com 'data' aninhado, desempacota
if (allItems.length === 1 && allItems[0].json.data) {
  rows = allItems[0].json.data;
} else {
  // Caso contrário, usa os itens diretamente
  rows = allItems.map(i => i.json);
}

const safeName = tableName.replace(/[^a-zA-Z0-9_\-]/g, '_');
const jsonContent = JSON.stringify({ tableName, tableId, totalRows: rows.length, rows }, null, 2);

// Gera CSV
let csvContent = '';
if (rows.length > 0) {
  const keys = Object.keys(rows[0]);
  csvContent += keys.join(',') + '\n';
  rows.forEach(row => {
    const values = keys.map(k => {
      const v = row[k];
      if (v === null || v === undefined) return '';
      const s = String(v);
      return s.includes(',') || s.includes('"') || s.includes('\n')
        ? '"' + s.replace(/"/g, '""') + '"'
        : s;
    });
    csvContent += values.join(',') + '\n';
  });
} else {
  csvContent = 'vazio\n';
}

return [{
  json: {
    tableId, tableName, safeName, repositorio,
    username: $('Code - Mapear Variaveis').item.json.username,
    token: $('Code - Mapear Variaveis').item.json.token,
    nome: $('Code - Mapear Variaveis').item.json.nome,
    email: $('Code - Mapear Variaveis').item.json.email,
    jsonContent, csvContent,
    totalRows: rows.length
  }
}];

// Passa os dados adiante mantendo as informações
return [{
  json: {
    exitCode: $input.item.json.exitCode || 0,
    stdout: $input.item.json.stdout || '',
    stderr: $input.item.json.stderr || '',
    tableName: $('Code - Montar JSON e CSV').item.json.tableName,
    repositorio: $('Code - Montar JSON e CSV').item.json.repositorio,
    processed: true
  }
}];
